#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    const long long MOD = 1000000007;
    int n;
    std::cin >> n;
    int size = 2 * n;
    std::vector<std::vector<long long>> ways(size, std::vector<long long>(n + 1, 0));
    long long tWays = 0;
    ways[0][0] = 1;

    for (int i = 1; i < size; i++) {
        ways[i][0] = ways[i - 1][1];
        ways[i][n] = ways[i - 1][n - 1];
        for (int k = 1; k < n; k++) {
            ways[i][k] = (ways[i - 1][k - 1] + ways[i - 1][k + 1]) % MOD;
        }
        if (i % 2 == 1) {
            int limit = std::min(i, 2 * n - i);
            for (int k = 0; k <= limit; k++) {
                tWays = (tWays + ways[i][k]) % MOD;
            }
        }
    }
    std::cout << tWays << "\n";
    return 0;
}
